using System.Data; using FluentValidation; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore; using Npgsql; using SmartWaste.Application.Collection.DTOs.Requests; using SmartWaste.Application.Collection.DTOs.Responses; using SmartWaste.Application.Collection.Interfaces; using SmartWaste.Application.Collection.Validation; using SmartWaste.Application.Common.Exceptions; using SmartWaste.Application.Fleet.DTOs.Responses; using SmartWaste.Application.Fleet.Services; using SmartWaste.Domain.Collection.Entities; using SmartWaste.Domain.Collection.Enums; using SmartWaste.Domain.Common; using SmartWaste.Domain.Entities; using SmartWaste.Domain.Reporting.Entities; using SmartWaste.Domain.Reporting.Enums; using SmartWaste.Infrastructure.Persistence;
namespace SmartWaste.Infrastructure.Collection.Services;
public sealed class CollectionAssignmentService(AppDbContext db, UserManager<AppUser> users) : ICollectionAssignmentService
{
 private readonly CreateCollectionAssignmentRequestValidator _validator=new();
 private readonly ReorderRouteStopsRequestValidator _reorderValidator=new();
 private readonly CancelCollectionAssignmentRequestValidator _cancelValidator=new();
 private readonly FailRouteStopRequestValidator _failStopValidator=new();
 private readonly RecordBinObservationRequestValidator _observationValidator=new();
    public async Task<AssignmentDetailDto> CreateAsync(CreateCollectionAssignmentRequest r, Guid actor, string role, CancellationToken ct = default)
    {
        if (role != AppRoles.WasteOfficer)
            throw new ForbiddenException("Only Waste Officers can create collection assignments.");
        return await ExecuteCreateAssignmentAsync(r, actor, role, ct);
    }

    public async Task<AssignmentDetailDto> CreateAssignmentFromApprovedPlanAsync(CreateCollectionAssignmentRequest r, Guid managerUserId, CancellationToken ct = default)
    {
        return await ExecuteCreateAssignmentAsync(r, managerUserId, AppRoles.MunicipalManager, ct);
    }

    private async Task<AssignmentDetailDto> ExecuteCreateAssignmentAsync(CreateCollectionAssignmentRequest r, Guid actor, string role, CancellationToken ct)
    {
        var valid = await _validator.ValidateAsync(r, ct);
        if (!valid.IsValid) throw new ValidationException(valid.Errors);
        if (!r.CollectionTaskIds.OrderBy(x => x).SequenceEqual(r.Stops.Select(x => x.CollectionTaskId).OrderBy(x => x)))
            throw new ValidationException("Stops must reference every selected task exactly once.");

        var isInMemory = db.Database.ProviderName?.Contains("InMemory") == true;
        await using var tx = (isInMemory || db.Database.CurrentTransaction != null)
            ? null
            : await db.Database.BeginTransactionAsync(ct);

        try
        {
            var driver = await db.DriverProfiles.Include(x => x.User).SingleOrDefaultAsync(x => x.UserId == r.DriverId, ct)
                ?? throw new NotFoundException("Driver availability profile was not found.");
            if (driver.User is null || !driver.User.IsActive || driver.AvailabilityStatus != DriverAvailabilityStatus.Available || !await users.IsInRoleAsync(driver.User, AppRoles.Driver))
                throw new BusinessRuleConflictException("Driver is not available for a new assignment.");

            var vehicle = await db.Vehicles.Include(x => x.SupportedWasteTypes).SingleOrDefaultAsync(x => x.Id == r.VehicleId, ct)
                ?? throw new NotFoundException("Vehicle was not found.");
            if (vehicle.OperationalStatus != VehicleOperationalStatus.Available)
                throw new BusinessRuleConflictException("Vehicle is not available.");

            if (await db.CollectionAssignments.AnyAsync(x => (x.Status == CollectionAssignmentStatus.Assigned || x.Status == CollectionAssignmentStatus.InProgress) && (x.DriverId == r.DriverId || x.VehicleId == r.VehicleId), ct))
                throw new BusinessRuleConflictException("Driver or vehicle already has an unfinished assignment.");

            var tasks = await db.CollectionTasks.Include(x => x.WasteReport).Include(x => x.WasteBin).ThenInclude(x => x!.AcceptedWasteTypes).Where(x => r.CollectionTaskIds.Contains(x.Id)).ToListAsync(ct);
            if (tasks.Count != r.CollectionTaskIds.Count) throw new NotFoundException("One or more collection tasks were not found.");
            if (tasks.Any(x => x.Status != CollectionTaskStatus.Scheduled)) throw new BusinessRuleConflictException("All selected tasks must be Scheduled.");
            if (tasks.Any(x => !x.WasteReportId.HasValue && !x.WasteBinId.HasValue)) throw new BusinessRuleConflictException("A selected task has no valid target.");
            if (await db.CollectionAssignmentTaskClaims.AnyAsync(x => x.IsActive && r.CollectionTaskIds.Contains(x.CollectionTaskId), ct))
                throw new BusinessRuleConflictException("A selected task is already assigned.");

            var requiresAck = RequiresAcknowledgement(tasks, vehicle);
            if (IsIncompatible(tasks, vehicle))
                throw new BusinessRuleConflictException("The selected vehicle is incompatible with the selected waste handling requirements.");
            if (requiresAck && (string.IsNullOrWhiteSpace(r.CompatibilityAcknowledgement) || r.CompatibilityAcknowledgement.Trim().Length < 5))
                throw new BusinessRuleConflictException("Waste-handling uncertainty requires an officer acknowledgement.");

            var now = DateTime.UtcNow;
            var a = new CollectionAssignment
            {
                DriverId = driver.UserId,
                VehicleId = vehicle.Id,
                AssignedByUserId = actor,
                Status = CollectionAssignmentStatus.Assigned,
                AssignedAt = now,
                CreatedAt = now,
                CompatibilityAcknowledgement = requiresAck ? r.CompatibilityAcknowledgement!.Trim() : null,
                CompatibilityAcknowledgedByUserId = requiresAck ? actor : null,
                CompatibilityAcknowledgedAt = requiresAck ? now : null
            };
            var route = new Route
            {
                CollectionAssignmentId = a.Id,
                RoutingMethod = RoutingMethod.ManualOrder,
                CreatedAt = now
            };
            a.Route = route;
            db.CollectionAssignments.Add(a);
            db.CollectionAssignmentStatusHistories.Add(new CollectionAssignmentStatusHistory
            {
                CollectionAssignmentId = a.Id,
                ToStatus = CollectionAssignmentStatus.Assigned,
                ChangedByUserId = actor,
                ChangedAt = now
            });

            foreach (var stopRequest in r.Stops.OrderBy(x => x.Sequence))
            {
                var task = tasks.Single(x => x.Id == stopRequest.CollectionTaskId);
                var claim = new CollectionAssignmentTaskClaim
                {
                    CollectionAssignmentId = a.Id,
                    CollectionTaskId = task.Id,
                    IsActive = true,
                    ClaimedAt = now
                };
                db.CollectionAssignmentTaskClaims.Add(claim);
                var stop = new RouteStop
                {
                    RouteId = route.Id,
                    CollectionTaskId = task.Id,
                    CollectionAssignmentTaskClaimId = claim.Id,
                    Sequence = stopRequest.Sequence,
                    Status = RouteStopStatus.Pending,
                    CreatedAt = now
                };
                route.Stops.Add(stop);
                db.RouteStopStatusHistories.Add(new RouteStopStatusHistory
                {
                    RouteStopId = stop.Id,
                    ToStatus = RouteStopStatus.Pending,
                    ChangedByUserId = actor,
                    ChangedAt = now
                });
                task.Status = CollectionTaskStatus.Assigned;
                task.UpdatedAt = now;
                db.CollectionTaskStatusHistories.Add(new CollectionTaskStatusHistory
                {
                    CollectionTaskId = task.Id,
                    FromStatus = CollectionTaskStatus.Scheduled,
                    ToStatus = CollectionTaskStatus.Assigned,
                    ChangedByUserId = actor,
                    ChangedAt = now,
                    Notes = role == AppRoles.MunicipalManager
                        ? "Assigned from approved AI dispatch plan."
                        : "Assigned to a manual collection assignment."
                });
            }

            await db.SaveChangesAsync(ct);
            if (tx != null) await tx.CommitAsync(ct);
            return await new AssignmentReadService(db).GetDetailAsync(a.Id, actor, role, ct);
        }
        catch (DbUpdateException ex) when (ex.InnerException is PostgresException { SqlState: PostgresErrorCodes.UniqueViolation })
        {
            if (tx != null) await tx.RollbackAsync(ct);
            throw new BusinessRuleConflictException("A selected resource or task was claimed by another assignment.");
        }
        catch
        {
            if (tx != null) await tx.RollbackAsync(ct);
            throw;
        }
    }

 private static bool IsIncompatible(IEnumerable<CollectionTask> tasks,Vehicle vehicle)=>FleetWasteCompatibilityEvaluator.Evaluate(tasks,vehicle).Status==FleetCompatibilityStatus.Incompatible;
 private static bool RequiresAcknowledgement(IEnumerable<CollectionTask> tasks,Vehicle vehicle)=>FleetWasteCompatibilityEvaluator.Evaluate(tasks,vehicle).RequiresAcknowledgement;
 public async Task<RouteReadDto> ReorderStopsAsync(Guid assignmentId,ReorderRouteStopsRequest request,Guid actor,string role,CancellationToken ct=default){if(role!=AppRoles.WasteOfficer)throw new ForbiddenException("Only Waste Officers can reorder manual routes.");var valid=await _reorderValidator.ValidateAsync(request,ct);if(!valid.IsValid)throw new ValidationException(valid.Errors);await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var assignment=await db.CollectionAssignments.Include(x=>x.Route!).ThenInclude(x=>x.Stops).SingleOrDefaultAsync(x=>x.Id==assignmentId,ct)??throw new NotFoundException("Collection assignment was not found.");if(assignment.Status!=CollectionAssignmentStatus.Assigned)throw new BusinessRuleConflictException("Only unstarted assignments can be reordered.");var route=assignment.Route??throw new BusinessRuleConflictException("Assignment has no route.");if(route.RoutingMethod!=RoutingMethod.ManualOrder)throw new BusinessRuleConflictException("Only manual routes can be reordered.");if(route.Stops.Any(x=>x.Status!=RouteStopStatus.Pending||x.CompletedAt.HasValue||x.FailedAt.HasValue))throw new BusinessRuleConflictException("Executed route stops cannot be reordered.");if(route.Stops.Count!=request.Stops.Count||!route.Stops.Select(x=>x.Id).OrderBy(x=>x).SequenceEqual(request.Stops.Select(x=>x.RouteStopId).OrderBy(x=>x)))throw new ValidationException("The request must contain every stop on this route exactly once.");var desired=request.Stops.ToDictionary(x=>x.RouteStopId,x=>x.Sequence);if(route.Stops.All(x=>x.Sequence==desired[x.Id]))return await new AssignmentReadService(db).GetRouteAsync(route.Id,actor,role,ct);var maxSequence=route.Stops.Max(x=>x.Sequence);if(maxSequence>int.MaxValue-route.Stops.Count-1)throw new BusinessRuleConflictException("Route stop sequences cannot be safely reordered.");var temporaryBase=maxSequence+route.Stops.Count+1;foreach(var stop in route.Stops)stop.Sequence=temporaryBase+stop.Sequence;await db.SaveChangesAsync(ct);foreach(var stop in route.Stops)stop.Sequence=desired[stop.Id];route.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return await new AssignmentReadService(db).GetRouteAsync(route.Id,actor,role,ct);}catch{await tx.RollbackAsync(ct);throw;}}
 public async Task<AssignmentDetailDto> CancelAsync(Guid assignmentId,CancelCollectionAssignmentRequest request,Guid actor,string role,CancellationToken ct=default){if(role!=AppRoles.WasteOfficer&&role!=AppRoles.MunicipalManager)throw new ForbiddenException("Only authorized staff can cancel collection assignments.");var valid=await _cancelValidator.ValidateAsync(request,ct);if(!valid.IsValid)throw new ValidationException(valid.Errors);var reason=request.Reason.Trim();await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var assignment=await db.CollectionAssignments.Include(x=>x.TaskClaims).ThenInclude(x=>x.CollectionTask).Include(x=>x.Route!).ThenInclude(x=>x.Stops).SingleOrDefaultAsync(x=>x.Id==assignmentId,ct)??throw new NotFoundException("Collection assignment was not found.");if(assignment.Status!=CollectionAssignmentStatus.Assigned)throw new BusinessRuleConflictException("Only unstarted assignments can be cancelled.");var route=assignment.Route??throw new BusinessRuleConflictException("Assignment has no route.");if(route.Stops.Any(x=>x.Status!=RouteStopStatus.Pending||x.CompletedAt.HasValue||x.FailedAt.HasValue))throw new BusinessRuleConflictException("Assignments with executed route stops cannot be cancelled.");var activeClaims=assignment.TaskClaims.Where(x=>x.IsActive).ToList();if(activeClaims.Count!=route.Stops.Count||activeClaims.Any(x=>x.CollectionTask is null||x.CollectionTask.Status!=CollectionTaskStatus.Assigned)||route.Stops.Any(x=>!activeClaims.Any(c=>c.Id==x.CollectionAssignmentTaskClaimId&&c.CollectionTaskId==x.CollectionTaskId&&c.CollectionAssignmentId==assignment.Id)))throw new BusinessRuleConflictException("Assignment task claims are not consistent with its route and tasks.");var now=DateTime.UtcNow;assignment.Status=CollectionAssignmentStatus.Cancelled;assignment.CancelledAt=now;assignment.CancellationReason=reason;assignment.UpdatedAt=now;db.CollectionAssignmentStatusHistories.Add(new CollectionAssignmentStatusHistory{CollectionAssignmentId=assignment.Id,FromStatus=CollectionAssignmentStatus.Assigned,ToStatus=CollectionAssignmentStatus.Cancelled,ChangedByUserId=actor,ChangedAt=now,Notes=reason});foreach(var claim in activeClaims){claim.IsActive=false;claim.ReleasedAt=now;claim.ReleasedByUserId=actor;claim.ReleaseReason=reason;var task=claim.CollectionTask!;task.Status=CollectionTaskStatus.Scheduled;task.UpdatedAt=now;db.CollectionTaskStatusHistories.Add(new CollectionTaskStatusHistory{CollectionTaskId=task.Id,FromStatus=CollectionTaskStatus.Assigned,ToStatus=CollectionTaskStatus.Scheduled,ChangedByUserId=actor,ChangedAt=now,Notes=reason});}await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return await new AssignmentReadService(db).GetDetailAsync(assignment.Id,actor,role,ct);}catch(DbUpdateException ex) when(ex.InnerException is PostgresException {SqlState:PostgresErrorCodes.SerializationFailure}){await tx.RollbackAsync(ct);throw new BusinessRuleConflictException("The assignment changed while cancellation was in progress. Retry the operation.");}catch(PostgresException ex) when(ex.SqlState==PostgresErrorCodes.SerializationFailure){await tx.RollbackAsync(ct);throw new BusinessRuleConflictException("The assignment changed while cancellation was in progress. Retry the operation.");}catch{await tx.RollbackAsync(ct);throw;}}
 public async Task<AssignmentDetailDto> StartAsync(Guid assignmentId,Guid actor,string role,CancellationToken ct=default){if(role!=AppRoles.Driver)throw new ForbiddenException("Only Drivers can start collection assignments.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var profile=await db.DriverProfiles.Include(x=>x.User).SingleOrDefaultAsync(x=>x.UserId==actor,ct)??throw new NotFoundException("Driver profile was not found.");if(profile.User is null||!profile.User.IsActive)throw new BusinessRuleConflictException("Inactive Driver accounts cannot start collection assignments.");var assignment=await db.CollectionAssignments.Include(x=>x.TaskClaims).ThenInclude(x=>x.CollectionTask!).ThenInclude(x=>x.WasteReport).Include(x=>x.TaskClaims).ThenInclude(x=>x.CollectionTask!).ThenInclude(x=>x.WasteBin).Include(x=>x.Route!).ThenInclude(x=>x.Stops).SingleOrDefaultAsync(x=>x.Id==assignmentId,ct)??throw new NotFoundException("Collection assignment was not found.");if(assignment.DriverId!=actor)throw new ForbiddenException("You are not authorized to start this assignment.");if(assignment.Status!=CollectionAssignmentStatus.Assigned)throw new BusinessRuleConflictException("Only assigned collection runs can be started.");var route=assignment.Route??throw new BusinessRuleConflictException("Assignment has no route.");if(route.Stops.Any(x=>x.Status!=RouteStopStatus.Pending||x.CompletedAt.HasValue||x.FailedAt.HasValue))throw new BusinessRuleConflictException("Assignments with executed route stops cannot be started.");var activeClaims=assignment.TaskClaims.Where(x=>x.IsActive).ToList();if(activeClaims.Count!=route.Stops.Count||activeClaims.Any(x=>x.CollectionTask is null||x.CollectionTask.Status!=CollectionTaskStatus.Assigned)||route.Stops.Any(x=>!activeClaims.Any(c=>c.Id==x.CollectionAssignmentTaskClaimId&&c.CollectionTaskId==x.CollectionTaskId&&c.CollectionAssignmentId==assignment.Id)))throw new BusinessRuleConflictException("Assignment task claims are not consistent with its route and tasks.");if(activeClaims.Any(x=>x.CollectionTask!.WasteReportId.HasValue&& (x.CollectionTask.WasteReport is null||x.CollectionTask.WasteReport.Status!=WasteReportStatus.Scheduled)||x.CollectionTask!.WasteBinId.HasValue&&x.CollectionTask.WasteBin is null||!x.CollectionTask!.WasteReportId.HasValue&&!x.CollectionTask.WasteBinId.HasValue))throw new BusinessRuleConflictException("A collection task source is not in a valid state to start.");var now=DateTime.UtcNow;assignment.Status=CollectionAssignmentStatus.InProgress;assignment.StartedAt=now;assignment.UpdatedAt=now;db.CollectionAssignmentStatusHistories.Add(new CollectionAssignmentStatusHistory{CollectionAssignmentId=assignment.Id,FromStatus=CollectionAssignmentStatus.Assigned,ToStatus=CollectionAssignmentStatus.InProgress,ChangedByUserId=actor,ChangedAt=now,Notes="Started by assigned Driver."});foreach(var claim in activeClaims){var task=claim.CollectionTask!;task.Status=CollectionTaskStatus.InProgress;task.UpdatedAt=now;db.CollectionTaskStatusHistories.Add(new CollectionTaskStatusHistory{CollectionTaskId=task.Id,FromStatus=CollectionTaskStatus.Assigned,ToStatus=CollectionTaskStatus.InProgress,ChangedByUserId=actor,ChangedAt=now,Notes="Collection run started by assigned Driver."});if(task.WasteReport is not null){task.WasteReport.Status=WasteReportStatus.InProgress;task.WasteReport.UpdatedAt=now;db.WasteReportStatusHistories.Add(new WasteReportStatusHistory{WasteReportId=task.WasteReport.Id,FromStatus=WasteReportStatus.Scheduled,ToStatus=WasteReportStatus.InProgress,ChangedByUserId=actor,ChangedAt=now,Notes="Collection run started by assigned Driver."});}}await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return await new AssignmentReadService(db).GetDetailAsync(assignment.Id,actor,role,ct);}catch(DbUpdateException ex) when(ex.InnerException is PostgresException {SqlState:PostgresErrorCodes.SerializationFailure}){await tx.RollbackAsync(ct);throw new BusinessRuleConflictException("The assignment changed while start was in progress. Retry the operation.");}catch(PostgresException ex) when(ex.SqlState==PostgresErrorCodes.SerializationFailure){await tx.RollbackAsync(ct);throw new BusinessRuleConflictException("The assignment changed while start was in progress. Retry the operation.");}catch{await tx.RollbackAsync(ct);throw;}}
 public async Task<AssignmentDetailDto> CompleteStopAsync(Guid assignmentId,Guid stopId,Guid actor,string role,CancellationToken ct=default)=>await ApplyStopOutcomeAsync(assignmentId,stopId,null,actor,role,ct);
 public async Task<AssignmentDetailDto> FailStopAsync(Guid assignmentId,Guid stopId,FailRouteStopRequest request,Guid actor,string role,CancellationToken ct=default){var valid=await _failStopValidator.ValidateAsync(request,ct);if(!valid.IsValid)throw new ValidationException(valid.Errors);return await ApplyStopOutcomeAsync(assignmentId,stopId,request.Reason.Trim(),actor,role,ct);}
 public async Task<AssignmentDetailDto> FinalizeAsync(Guid assignmentId,Guid actor,string role,CancellationToken ct=default){if(role!=AppRoles.Driver)throw new ForbiddenException("Only Drivers can finalize collection assignments.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var assignment=await db.CollectionAssignments.Include(x=>x.TaskClaims).ThenInclude(x=>x.CollectionTask).Include(x=>x.Route!).ThenInclude(x=>x.Stops).SingleOrDefaultAsync(x=>x.Id==assignmentId,ct)??throw new NotFoundException("Collection assignment was not found.");if(assignment.DriverId!=actor)throw new ForbiddenException("You are not authorized to finalize this assignment.");if(assignment.Status!=CollectionAssignmentStatus.InProgress)throw new BusinessRuleConflictException("Only in-progress assignments can be finalized.");var route=assignment.Route??throw new BusinessRuleConflictException("Assignment has no route.");if(route.Stops.Count==0)throw new BusinessRuleConflictException("Assignments without route stops cannot be finalized.");var activeClaims=assignment.TaskClaims.Where(x=>x.IsActive).ToList();if(activeClaims.Count!=assignment.TaskClaims.Count||activeClaims.Count!=route.Stops.Count)throw new BusinessRuleConflictException("Assignment task claims are not consistent with its route.");foreach(var stop in route.Stops){if(stop.Status==RouteStopStatus.Pending||!stop.CompletedAt.HasValue&&!stop.FailedAt.HasValue)throw new BusinessRuleConflictException("Every route stop must have a terminal outcome before finalization.");if(stop.Status==RouteStopStatus.Completed&&(stop.CompletedAt is null||stop.FailedAt.HasValue||stop.FailureReason is not null))throw new BusinessRuleConflictException("A completed route stop has invalid outcome data.");if(stop.Status==RouteStopStatus.Failed&&(stop.FailedAt is null||string.IsNullOrWhiteSpace(stop.FailureReason)))throw new BusinessRuleConflictException("A failed route stop has invalid outcome data.");var claim=activeClaims.SingleOrDefault(x=>x.Id==stop.CollectionAssignmentTaskClaimId&&x.CollectionAssignmentId==assignment.Id&&x.CollectionTaskId==stop.CollectionTaskId)??throw new BusinessRuleConflictException("Route stop claim is not valid for this assignment.");var expected=stop.Status==RouteStopStatus.Completed?CollectionTaskStatus.Completed:CollectionTaskStatus.Failed;if(claim.CollectionTask is null||claim.CollectionTask.Status!=expected)throw new BusinessRuleConflictException("Route stop task outcome is not consistent with the assignment.");}var hasCompleted=route.Stops.Any(x=>x.Status==RouteStopStatus.Completed);var hasFailed=route.Stops.Any(x=>x.Status==RouteStopStatus.Failed);var finalStatus=hasCompleted&&hasFailed?CollectionAssignmentStatus.PartiallyCompleted:hasCompleted?CollectionAssignmentStatus.Completed:CollectionAssignmentStatus.Failed;var now=DateTime.UtcNow;assignment.Status=finalStatus;assignment.FinalizedAt=now;assignment.UpdatedAt=now;db.CollectionAssignmentStatusHistories.Add(new CollectionAssignmentStatusHistory{CollectionAssignmentId=assignment.Id,FromStatus=CollectionAssignmentStatus.InProgress,ToStatus=finalStatus,ChangedByUserId=actor,ChangedAt=now,Notes="Finalized by assigned Driver."});foreach(var claim in activeClaims){claim.IsActive=false;claim.ReleasedAt=now;claim.ReleasedByUserId=actor;claim.ReleaseReason="Assignment finalized.";}await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return await new AssignmentReadService(db).GetDetailAsync(assignment.Id,actor,role,ct);}catch(DbUpdateException ex) when(ex.InnerException is PostgresException {SqlState:PostgresErrorCodes.SerializationFailure}){await tx.RollbackAsync(ct);throw new BusinessRuleConflictException("The assignment changed while finalization was in progress. Retry the operation.");}catch(PostgresException ex) when(ex.SqlState==PostgresErrorCodes.SerializationFailure){await tx.RollbackAsync(ct);throw new BusinessRuleConflictException("The assignment changed while finalization was in progress. Retry the operation.");}catch{await tx.RollbackAsync(ct);throw;}}
 public async Task<BinObservationDto> RecordDriverBinObservationAsync(Guid assignmentId,Guid stopId,RecordBinObservationRequest request,Guid actor,string role,CancellationToken ct=default){if(role!=AppRoles.Driver)throw new ForbiddenException("Only Drivers can record assignment bin observations.");var valid=await _observationValidator.ValidateAsync(request,ct);if(!valid.IsValid)throw new ValidationException(valid.Errors);await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var assignment=await db.CollectionAssignments.Include(x=>x.TaskClaims).ThenInclude(x=>x.CollectionTask).Include(x=>x.Route!).ThenInclude(x=>x.Stops).SingleOrDefaultAsync(x=>x.Id==assignmentId,ct)??throw new NotFoundException("Collection assignment was not found.");if(assignment.DriverId!=actor)throw new ForbiddenException("You are not authorized to record an observation for this assignment.");if(assignment.Status!=CollectionAssignmentStatus.InProgress&&assignment.Status!=CollectionAssignmentStatus.Completed&&assignment.Status!=CollectionAssignmentStatus.PartiallyCompleted)throw new BusinessRuleConflictException("This assignment is not eligible for a Driver bin observation.");var route=assignment.Route??throw new BusinessRuleConflictException("Assignment has no route.");var stop=route.Stops.SingleOrDefault(x=>x.Id==stopId)??throw new NotFoundException("Route stop was not found.");if(stop.Status!=RouteStopStatus.Completed||!stop.CompletedAt.HasValue||stop.FailedAt.HasValue)throw new BusinessRuleConflictException("Only a completed route stop is eligible for a Driver bin observation.");var claim=assignment.TaskClaims.SingleOrDefault(x=>x.Id==stop.CollectionAssignmentTaskClaimId&&x.CollectionAssignmentId==assignment.Id&&x.CollectionTaskId==stop.CollectionTaskId)??throw new BusinessRuleConflictException("Route stop claim is not valid for this assignment.");var task=claim.CollectionTask??throw new BusinessRuleConflictException("Route stop task was not found.");if(!task.WasteBinId.HasValue||task.WasteReportId.HasValue||task.Status!=CollectionTaskStatus.Completed)throw new BusinessRuleConflictException("Only a completed bin-targeted task is eligible for a Driver observation.");var bin=await db.WasteBins.SingleOrDefaultAsync(x=>x.Id==task.WasteBinId.Value,ct)??throw new NotFoundException("Waste bin was not found.");if(bin.AdministrativeStatus==BinAdministrativeStatus.Retired)throw new BusinessRuleConflictException("Cannot record an observation for a retired waste bin.");var now=DateTime.UtcNow;var observation=new BinObservation{WasteBinId=bin.Id,FillLevelPercent=request.FillLevelPercent!.Value,Condition=request.Condition!.Value,Notes=string.IsNullOrWhiteSpace(request.Notes)?null:request.Notes.Trim(),RecordedByUserId=actor,RecordedAt=now};db.BinObservations.Add(observation);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);var user=await db.Users.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==actor,ct);return new BinObservationDto{Id=observation.Id,WasteBinId=observation.WasteBinId,FillLevelPercent=observation.FillLevelPercent,Condition=observation.Condition,Notes=observation.Notes,RecordedByUserId=actor,RecordedByUserName=user?.FullName??user?.UserName??"Driver",RecordedAt=observation.RecordedAt};}catch(DbUpdateException ex) when(ex.InnerException is PostgresException {SqlState:PostgresErrorCodes.SerializationFailure}){await tx.RollbackAsync(ct);throw new BusinessRuleConflictException("The assignment changed while observation recording was in progress. Retry the operation.");}catch(PostgresException ex) when(ex.SqlState==PostgresErrorCodes.SerializationFailure){await tx.RollbackAsync(ct);throw new BusinessRuleConflictException("The assignment changed while observation recording was in progress. Retry the operation.");}catch{await tx.RollbackAsync(ct);throw;}}
 private async Task<AssignmentDetailDto> ApplyStopOutcomeAsync(Guid assignmentId,Guid stopId,string? failureReason,Guid actor,string role,CancellationToken ct){if(role!=AppRoles.Driver)throw new ForbiddenException("Only Drivers can record route stop outcomes.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var assignment=await db.CollectionAssignments.Include(x=>x.TaskClaims).ThenInclude(x=>x.CollectionTask!).ThenInclude(x=>x.WasteReport).Include(x=>x.TaskClaims).ThenInclude(x=>x.CollectionTask!).ThenInclude(x=>x.WasteBin).Include(x=>x.Route!).ThenInclude(x=>x.Stops).SingleOrDefaultAsync(x=>x.Id==assignmentId,ct)??throw new NotFoundException("Collection assignment was not found.");if(assignment.DriverId!=actor)throw new ForbiddenException("You are not authorized to update this assignment.");if(assignment.Status!=CollectionAssignmentStatus.InProgress)throw new BusinessRuleConflictException("Only in-progress assignments can record stop outcomes.");var route=assignment.Route??throw new BusinessRuleConflictException("Assignment has no route.");var stop=route.Stops.SingleOrDefault(x=>x.Id==stopId)??throw new NotFoundException("Route stop was not found.");if(stop.Status!=RouteStopStatus.Pending||stop.CompletedAt.HasValue||stop.FailedAt.HasValue)throw new BusinessRuleConflictException("This route stop already has an outcome.");var claim=assignment.TaskClaims.SingleOrDefault(x=>x.Id==stop.CollectionAssignmentTaskClaimId&&x.IsActive&&x.CollectionTaskId==stop.CollectionTaskId&&x.CollectionAssignmentId==assignment.Id)??throw new BusinessRuleConflictException("Route stop claim is not valid for this assignment.");var task=claim.CollectionTask??throw new BusinessRuleConflictException("Route stop task was not found.");if(task.Status!=CollectionTaskStatus.InProgress)throw new BusinessRuleConflictException("Route stop task is not in progress.");if((task.WasteReportId.HasValue==task.WasteBinId.HasValue)||(task.WasteReportId.HasValue&&task.WasteReport is null)||(task.WasteBinId.HasValue&&task.WasteBin is null)||(task.WasteReport is not null&&task.WasteReport.Status!=WasteReportStatus.InProgress))throw new BusinessRuleConflictException("Route stop task source is not valid.");var now=DateTime.UtcNow;var failed=failureReason is not null;stop.Status=failed?RouteStopStatus.Failed:RouteStopStatus.Completed;stop.UpdatedAt=now;if(failed){stop.FailedAt=now;stop.FailureReason=failureReason;}else{stop.CompletedAt=now;}db.RouteStopStatusHistories.Add(new RouteStopStatusHistory{RouteStopId=stop.Id,FromStatus=RouteStopStatus.Pending,ToStatus=stop.Status,ChangedByUserId=actor,ChangedAt=now,Notes=failureReason});task.Status=failed?CollectionTaskStatus.Failed:CollectionTaskStatus.Completed;task.UpdatedAt=now;db.CollectionTaskStatusHistories.Add(new CollectionTaskStatusHistory{CollectionTaskId=task.Id,FromStatus=CollectionTaskStatus.InProgress,ToStatus=task.Status,ChangedByUserId=actor,ChangedAt=now,Notes=failureReason});if(!failed&&task.WasteReport is not null){task.WasteReport.Status=WasteReportStatus.Resolved;task.WasteReport.UpdatedAt=now;db.WasteReportStatusHistories.Add(new WasteReportStatusHistory{WasteReportId=task.WasteReport.Id,FromStatus=WasteReportStatus.InProgress,ToStatus=WasteReportStatus.Resolved,ChangedByUserId=actor,ChangedAt=now,Notes="Collection completed by assigned Driver."});}if(!failed&&task.WasteBin is not null)task.WasteBin.LastCollectedAt=now;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return await new AssignmentReadService(db).GetDetailAsync(assignment.Id,actor,role,ct);}catch(DbUpdateException ex) when(ex.InnerException is PostgresException {SqlState:PostgresErrorCodes.SerializationFailure}){await tx.RollbackAsync(ct);throw new BusinessRuleConflictException("The route stop changed while its outcome was being recorded. Retry the operation.");}catch(PostgresException ex) when(ex.SqlState==PostgresErrorCodes.SerializationFailure){await tx.RollbackAsync(ct);throw new BusinessRuleConflictException("The route stop changed while its outcome was being recorded. Retry the operation.");}catch{await tx.RollbackAsync(ct);throw;}}
